-- Worldforged items upgraded from their base straight to the Zul'Gurub tier (#7934). ItemAddon.dbc lists a blue
-- dungeon variant (item level 60, f40 pointing at the base) for most bases, and the first-rank recipe skipped it.
-- The chain is now base -> dungeon variant (always open, the first rank's cost) -> Zul'Gurub tier (unchanged).
-- The new recipes take the dungeon variant's entry + 3000000 as their store key.
-- Bases already upgrading into their dungeon variant, or whose variant is in use elsewhere, are left alone.
DELETE FROM `worldforged_upgrade` WHERE (`base_item`, `target_item`) IN (
(202555, 1388061),
(217851, 1389875),
(217860, 1389876),
